ALTER TABLE public.announcements ADD COLUMN IF NOT EXISTS title text NOT NULL DEFAULT '';
ALTER TABLE public.announcements ADD COLUMN IF NOT EXISTS link_url text;
ALTER TABLE public.announcements ADD COLUMN IF NOT EXISTS updated_at timestamptz;
ALTER TABLE public.announcements ADD COLUMN IF NOT EXISTS archived_at timestamptz;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS communication_team_id uuid;
CREATE TABLE public.team_channel_preferences(team_id uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,user_id uuid NOT NULL,muted boolean NOT NULL DEFAULT false,announcements_read_at timestamptz,PRIMARY KEY(team_id,user_id));
GRANT SELECT ON public.team_channel_preferences TO authenticated;
GRANT ALL ON public.team_channel_preferences TO service_role;
ALTER TABLE public.team_channel_preferences ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.team_channel_access(_team uuid,_user uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND EXISTS(SELECT 1 FROM teams t WHERE t.id=_team AND NOT EXISTS(SELECT 1 FROM user_suspensions s WHERE s.user_id=_user) AND NOT EXISTS(SELECT 1 FROM team_suspensions s WHERE s.team_id=_team) AND NOT EXISTS(SELECT 1 FROM community_suspensions s WHERE s.team_id=_team AND s.user_id=_user AND s.revoked_at IS NULL AND s.scope_type='team') AND (t.owner_id=_user OR EXISTS(SELECT 1 FROM team_members m WHERE m.team_id=_team AND m.user_id=_user AND m.suspended_at IS NULL AND m.role IN ('leader','host','member')))); $$;
CREATE OR REPLACE FUNCTION public.team_channel_owner(_team uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT team_channel_access(_team) AND EXISTS(SELECT 1 FROM teams WHERE id=_team AND owner_id=auth.uid()); $$;
REVOKE ALL ON FUNCTION public.team_channel_access(uuid,uuid),public.team_channel_owner(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.team_channel_access(uuid,uuid),public.team_channel_owner(uuid) TO authenticated,service_role;
CREATE POLICY channel_preferences_own ON public.team_channel_preferences FOR SELECT TO authenticated USING(user_id=auth.uid() AND team_channel_access(team_id));
CREATE POLICY channel_announcement_read ON public.announcements AS RESTRICTIVE FOR SELECT TO authenticated USING(team_channel_access(team_id) AND (archived_at IS NULL OR team_channel_owner(team_id)));
CREATE POLICY channel_announcement_insert ON public.announcements AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(team_channel_owner(team_id));
CREATE POLICY channel_announcement_update ON public.announcements AS RESTRICTIVE FOR UPDATE TO authenticated USING(team_channel_owner(team_id)) WITH CHECK(team_channel_owner(team_id));
CREATE POLICY channel_announcement_delete ON public.announcements AS RESTRICTIVE FOR DELETE TO authenticated USING(team_channel_owner(team_id));
CREATE POLICY channel_topic_read ON public.discussion_topics AS RESTRICTIVE FOR SELECT TO authenticated USING(team_channel_access(team_id));
CREATE POLICY channel_activity_read ON public.activity AS RESTRICTIVE FOR SELECT TO authenticated USING(type<>'announcement_posted' OR team_channel_access(team_id));
CREATE POLICY channel_notification_read ON public.notifications AS RESTRICTIVE FOR SELECT TO authenticated USING(communication_team_id IS NULL OR team_channel_access(communication_team_id));
CREATE POLICY channel_notification_update ON public.notifications AS RESTRICTIVE FOR UPDATE TO authenticated USING(communication_team_id IS NULL OR team_channel_access(communication_team_id));
CREATE POLICY channel_topic_reads ON public.topic_reads AS RESTRICTIVE FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM discussion_topics t WHERE t.id=topic_id AND team_channel_access(t.team_id)));
CREATE OR REPLACE FUNCTION public.can_moderate_comment(_c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM comments c WHERE c.id=_c AND CASE WHEN c.topic_id IS NOT NULL THEN team_channel_owner(c.team_id) ELSE can_manage_event(c.event_id) OR team_capability(c.team_id,'moderate') OR has_workspace_assignment(c.team_id,auth.uid(),'moderation',c.event_id) END); $$;
CREATE OR REPLACE FUNCTION public.can_read_comment(_c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM comments c WHERE c.id=_c AND (CASE WHEN c.topic_id IS NOT NULL THEN team_channel_access(c.team_id) AND NOT EXISTS(SELECT 1 FROM community_suspensions s WHERE s.team_id=c.team_id AND s.user_id=auth.uid() AND s.scope_type='topic' AND s.scope_id=c.topic_id AND s.revoked_at IS NULL) ELSE can_join_conversation(c.event_id) END) AND (NOT c.hidden OR c.author_id=auth.uid() OR can_moderate_comment(c.id))); $$;
CREATE OR REPLACE FUNCTION public.channel_comment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.topic_id IS NOT NULL AND (NOT team_channel_access(NEW.team_id) OR NOT EXISTS(SELECT 1 FROM discussion_topics t WHERE t.id=NEW.topic_id AND t.team_id=NEW.team_id)) THEN RAISE EXCEPTION 'not_allowed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER channel_comment_guard BEFORE INSERT OR UPDATE ON public.comments FOR EACH ROW EXECUTE FUNCTION public.channel_comment_guard();
CREATE OR REPLACE FUNCTION public.channel_announcement_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND (NOT team_channel_owner(NEW.team_id) OR (TG_OP='UPDATE' AND (OLD.team_id IS DISTINCT FROM NEW.team_id OR OLD.author_id IS DISTINCT FROM NEW.author_id))) THEN RAISE EXCEPTION 'not_allowed'; END IF; IF NEW.link_url IS NOT NULL AND (NEW.link_url !~ '^https://[^ /\\]+([/?#].*)?$' OR NEW.link_url ~ '[[:cntrl:]]' OR NEW.link_url ~ '^https://[^/]*@') THEN RAISE EXCEPTION 'invalid_link'; END IF; IF length(NEW.title)>120 OR length(trim(NEW.body)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid_body'; END IF; IF TG_OP='UPDATE' AND (NEW.title,NEW.body,NEW.link_url) IS DISTINCT FROM (OLD.title,OLD.body,OLD.link_url) THEN NEW.updated_at=clock_timestamp(); END IF; RETURN NEW; END $$;
CREATE TRIGGER channel_announcement_guard BEFORE INSERT OR UPDATE ON public.announcements FOR EACH ROW EXECUTE FUNCTION public.channel_announcement_guard();
CREATE OR REPLACE FUNCTION public.channel_in_app(_team uuid,_kind text,_id uuid,_title text,_body text,_link text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO notifications(user_id,kind,title,body,link,dedupe_key,communication_team_id) SELECT p.id,_kind,left(_title,140),left(_body,200),_link,'team-channel:'||_kind||':'||_id||':'||p.id,_team FROM profiles p WHERE p.id<>auth.uid() AND team_channel_access(_team,p.id) AND NOT EXISTS(SELECT 1 FROM team_channel_preferences cp WHERE cp.team_id=_team AND cp.user_id=p.id AND cp.muted) AND coalesce((p.notify_prefs->>CASE WHEN _kind='announcement' THEN 'announcements' ELSE 'conversation' END)::boolean,true) ON CONFLICT(dedupe_key) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.channel_in_app(uuid,text,uuid,text,text,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.channel_announcement_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM channel_in_app(NEW.team_id,'announcement',NEW.id,coalesce(nullif(NEW.title,''),left(NEW.body,80)),NEW.body,'/team?team='||NEW.team_id||'&surface=announcements&announcement='||NEW.id); RETURN NEW; END $$;
CREATE TRIGGER channel_announcement_notify AFTER INSERT ON public.announcements FOR EACH ROW EXECUTE FUNCTION public.channel_announcement_notify();
CREATE OR REPLACE FUNCTION public.channel_comment_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.topic_id IS NOT NULL THEN PERFORM channel_in_app(NEW.team_id,'conversation',NEW.id,(SELECT title FROM discussion_topics WHERE id=NEW.topic_id),NEW.body,'/team?team='||NEW.team_id||'&surface=chat&topic='||NEW.topic_id||'&message='||NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER channel_comment_notify AFTER INSERT ON public.comments FOR EACH ROW EXECUTE FUNCTION public.channel_comment_notify();
CREATE OR REPLACE FUNCTION public.notify_announcement(_announcement uuid,_email boolean,_subteams boolean) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a announcements; BEGIN SELECT * INTO a FROM announcements WHERE id=_announcement; IF a.id IS NULL OR NOT team_channel_owner(a.team_id) THEN RAISE EXCEPTION 'not_allowed'; END IF; PERFORM channel_in_app(a.team_id,'announcement',a.id,coalesce(nullif(a.title,''),left(a.body,80)),a.body,'/team?team='||a.team_id||'&surface=announcements&announcement='||a.id); RETURN 0; END $$;
CREATE OR REPLACE FUNCTION public.save_team_announcement(_team uuid,_id uuid,_title text,_body text,_link text,_pinned boolean,_archived boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a announcements; BEGIN IF NOT team_channel_owner(_team) THEN RAISE EXCEPTION 'not_allowed'; END IF; IF has_blocked_claim(_title||' '||_body) THEN RAISE EXCEPTION 'blocked_claim'; END IF; IF _id IS NULL THEN INSERT INTO announcements(team_id,author_id,title,body,link_url,pinned) VALUES(_team,auth.uid(),trim(_title),trim(_body),nullif(trim(_link),''),_pinned) RETURNING * INTO a; ELSE UPDATE announcements SET title=trim(_title),body=trim(_body),link_url=nullif(trim(_link),''),pinned=_pinned,archived_at=CASE WHEN _archived THEN coalesce(archived_at,now()) END WHERE id=_id AND team_id=_team RETURNING * INTO a; IF NOT FOUND THEN RAISE EXCEPTION 'not_allowed'; END IF; END IF; RETURN a.id; END $$;
CREATE OR REPLACE FUNCTION public.team_channel_state(_team uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT team_channel_access(_team) THEN RETURN NULL; END IF; RETURN jsonb_build_object('owner',team_channel_owner(_team),'muted',coalesce((SELECT muted FROM team_channel_preferences WHERE team_id=_team AND user_id=auth.uid()),false),'announcements_unread',(SELECT count(*) FROM announcements a WHERE a.team_id=_team AND a.archived_at IS NULL AND a.author_id<>auth.uid() AND coalesce(a.updated_at,a.created_at)>coalesce((SELECT announcements_read_at FROM team_channel_preferences WHERE team_id=_team AND user_id=auth.uid()),'-infinity'::timestamptz)),'chat_unread',(SELECT count(*) FROM comments c WHERE c.team_id=_team AND c.topic_id IS NOT NULL AND c.author_id<>auth.uid() AND can_read_comment(c.id) AND c.created_at>coalesce((SELECT last_read_at FROM topic_reads WHERE topic_id=c.topic_id AND user_id=auth.uid()),'-infinity'::timestamptz))); END $$;
CREATE OR REPLACE FUNCTION public.set_team_channel_preference(_team uuid,_muted boolean DEFAULT NULL,_read_announcements boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT team_channel_access(_team) THEN RAISE EXCEPTION 'not_allowed'; END IF; INSERT INTO team_channel_preferences(team_id,user_id,muted,announcements_read_at) VALUES(_team,auth.uid(),coalesce(_muted,false),CASE WHEN _read_announcements THEN now() END) ON CONFLICT(team_id,user_id) DO UPDATE SET muted=coalesce(_muted,team_channel_preferences.muted),announcements_read_at=CASE WHEN _read_announcements THEN now() ELSE team_channel_preferences.announcements_read_at END; END $$;
CREATE OR REPLACE FUNCTION public.team_topics(_team uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN NOT team_channel_access(_team) THEN NULL ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'pinned',t.pinned,'last_post_at',t.last_post_at,'posts',(SELECT count(*) FROM comments c WHERE c.topic_id=t.id AND can_read_comment(c.id)),'unread',EXISTS(SELECT 1 FROM comments c WHERE c.topic_id=t.id AND c.author_id<>auth.uid() AND can_read_comment(c.id) AND c.created_at>coalesce((SELECT last_read_at FROM topic_reads r WHERE r.topic_id=t.id AND r.user_id=auth.uid()),'-infinity'::timestamptz))) ORDER BY t.pinned DESC,t.last_post_at DESC,t.id) FROM discussion_topics t WHERE t.team_id=_team AND NOT EXISTS(SELECT 1 FROM community_suspensions s WHERE s.team_id=_team AND s.user_id=auth.uid() AND s.scope_type='topic' AND s.scope_id=t.id AND s.revoked_at IS NULL)), '[]'::jsonb) END; $$;
CREATE OR REPLACE FUNCTION public.create_topic(_team uuid,_title text,_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE id uuid; BEGIN IF NOT team_channel_owner(_team) THEN RAISE EXCEPTION 'not_allowed'; END IF; IF length(trim(_title)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'invalid_title'; END IF; IF has_blocked_claim(_title) THEN RAISE EXCEPTION 'blocked_claim'; END IF; INSERT INTO discussion_topics(team_id,title,created_by) VALUES(_team,trim(_title),auth.uid()) RETURNING discussion_topics.id INTO id; IF length(trim(coalesce(_body,'')))>0 THEN PERFORM post_comment(NULL,id,NULL,_body,NULL); END IF; RETURN id; END $$;
CREATE OR REPLACE FUNCTION public.manage_topic(_id uuid,_pinned boolean,_delete boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tm uuid; BEGIN SELECT team_id INTO tm FROM discussion_topics WHERE id=_id; IF NOT team_channel_owner(tm) THEN RAISE EXCEPTION 'not_allowed'; END IF; IF coalesce(_delete,false) THEN DELETE FROM discussion_topics WHERE id=_id; ELSE UPDATE discussion_topics SET pinned=coalesce(_pinned,pinned) WHERE id=_id; END IF; END $$;
CREATE OR REPLACE FUNCTION public.mark_topic_read(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM discussion_topics WHERE id=_id AND team_channel_access(team_id)) THEN RAISE EXCEPTION 'not_allowed'; END IF; INSERT INTO topic_reads(topic_id,user_id) VALUES(_id,auth.uid()) ON CONFLICT(topic_id,user_id) DO UPDATE SET last_read_at=now(); END $$;
CREATE OR REPLACE FUNCTION public.delete_comment(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM comments WHERE id=_id AND can_read_comment(_id) AND (author_id=auth.uid() OR can_moderate_comment(_id))) THEN RAISE EXCEPTION 'not_allowed'; END IF; DELETE FROM comments WHERE id=_id; END $$;
DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.comment_feed(uuid,uuid)'::regprocedure) INTO d; d:=replace(d,'SELECT is_team_member(team_id, ARRAY[''leader'',''host'',''member'']), is_team_member(team_id, ARRAY[''leader''])','SELECT team_channel_access(team_id), team_channel_owner(team_id)'); d:=replace(d,'WHERE (c.event_id = _event OR c.topic_id = _topic) AND','WHERE (c.event_id = _event OR c.topic_id = _topic) AND can_read_comment(c.id) AND'); EXECUTE d; SELECT pg_get_functiondef('public.post_comment(uuid,uuid,uuid,text,uuid[])'::regprocedure) INTO d; d:=replace(d,'NOT is_team_member(_team, ARRAY[''leader'',''host'',''member''])','NOT team_channel_access(_team)'); d:=replace(d,'_url := ''/team?topic='' || _topic;','_url := ''/team?team='' || _team || ''&surface=chat&topic='' || _topic;'); d:=replace(d,'IF p.id IS NOT NULL AND p.author_id <> _uid THEN','IF _topic IS NULL AND p.id IS NOT NULL AND p.author_id <> _uid THEN'); d:=replace(d,'IF _m <> _uid AND _m IS DISTINCT FROM p.author_id AND is_member_of(_team, _m) THEN','IF _topic IS NULL AND _m <> _uid AND _m IS DISTINCT FROM p.author_id AND is_member_of(_team, _m) THEN'); EXECUTE d; SELECT pg_get_functiondef('public.search_team_library(uuid,text)'::regprocedure) INTO d; d:=replace(d,'AND c.tsv @@ _query','AND (c.source_type <> ''announcement'' OR (team_channel_access(c.team_id) AND EXISTS(SELECT 1 FROM announcements a WHERE a.id=c.source_id AND a.archived_at IS NULL))) AND c.tsv @@ _query'); EXECUTE d; END $patch$;
ALTER TABLE public.comments ADD COLUMN IF NOT EXISTS client_request_id uuid;
CREATE UNIQUE INDEX channel_comment_retry ON public.comments(author_id,client_request_id) WHERE client_request_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.post_team_comment(_topic uuid,_parent uuid,_body text,_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tm uuid; id uuid; c comments; BEGIN SELECT team_id INTO tm FROM discussion_topics WHERE discussion_topics.id=_topic; IF NOT team_channel_access(tm) OR _request IS NULL THEN RAISE EXCEPTION 'not_allowed'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()||':'||_request,0)); SELECT * INTO c FROM comments WHERE author_id=auth.uid() AND client_request_id=_request; IF FOUND THEN IF c.topic_id IS DISTINCT FROM _topic OR c.parent_id IS DISTINCT FROM _parent OR c.body IS DISTINCT FROM trim(_body) THEN RAISE EXCEPTION 'invalid_retry'; END IF; RETURN c.id; END IF; id:=post_comment(NULL,_topic,_parent,_body,NULL); UPDATE comments SET client_request_id=_request WHERE comments.id=id; RETURN id; END $$;
REVOKE ALL ON FUNCTION public.save_team_announcement(uuid,uuid,text,text,text,boolean,boolean),public.team_channel_state(uuid),public.set_team_channel_preference(uuid,boolean,boolean),public.post_team_comment(uuid,uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_team_announcement(uuid,uuid,text,text,text,boolean,boolean),public.team_channel_state(uuid),public.set_team_channel_preference(uuid,boolean,boolean),public.post_team_comment(uuid,uuid,text,uuid) TO authenticated;